-- Generated from application question bank. Not a live backend database.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE chapters (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE sections (id TEXT PRIMARY KEY, chapter_id INTEGER NOT NULL REFERENCES chapters(id), section_no INTEGER NOT NULL, name TEXT NOT NULL, is_review INTEGER NOT NULL CHECK(is_review IN (0,1)));
CREATE TABLE topics (id TEXT PRIMARY KEY, section_id TEXT NOT NULL REFERENCES sections(id), name TEXT NOT NULL, rule TEXT NOT NULL, method TEXT NOT NULL, pitfall TEXT NOT NULL);
CREATE TABLE questions (id TEXT PRIMARY KEY, topic_id TEXT NOT NULL REFERENCES topics(id), role TEXT NOT NULL CHECK(role IN ('example','practice')), difficulty TEXT CHECK(difficulty IN ('基础题','提高题','压轴题')), question_type TEXT NOT NULL, question_text TEXT NOT NULL, answer TEXT NOT NULL, steps_json TEXT NOT NULL, options_json TEXT NOT NULL, diagram_json TEXT);
CREATE INDEX questions_by_topic ON questions(topic_id);
CREATE INDEX questions_by_difficulty_type ON questions(difficulty,question_type);
COMMIT;
